sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    try {
        var body = request.body.data;

        gs.info('Scripted rest api type of body ' + typeof body);
        gs.info('Scripted rest api body ' + JSON.stringify(body));
        if (!body) {
            response.setStatus(400);
            response.setBody({
                error: 'Request body is required. Send a JSON object or array of server records.'
            });
            return;
        }

        //var servers = body instanceof Array ? body : [body];
        var servers = body;
        var insertedCount = 0;
        var insertedIds = [];
        var errors = [];
        var fields = ['source_system', 'payload', 'action', 'translated_event'];
        gs.info('Scripted rest api servers ' + JSON.stringify(servers));
        for (var i = 0; i < servers.length; i++) {
            var server = servers[i];
            //var gr = new GlideRecord('x_710945_server_0_server_stg');
            var gr = new GlideRecord('x_2226556_server_0_canopi_stg');
            gr.initialize();

            for (var f = 0; f < fields.length; f++) {
                var fieldName = fields[f];
                if (server[fieldName] !== undefined && server[fieldName] !== null) {
                    gs.info('Scripted rest api fieldName ' + String(server[fieldName]));
                    gr.setValue(fieldName, String(server[fieldName]));
                }
            }

            var sysId = gr.insert();
            if (sysId) {
                insertedCount++;
                insertedIds.push(String(sysId));
            } else {
                errors.push('Failed to insert record for server: ' + (server.server_name || 'unknown'));
            }
        }

        response.setStatus(insertedCount > 0 ? 201 : 400);
        response.setBody({
            result: insertedCount > 0 ? 'success' : 'failure',
            records_inserted: insertedCount,
            total_submitted: servers.length,
            inserted_sys_ids: insertedIds,
            errors: errors
        });
    } catch (err) {
        gs.info('Scripted rest api fieldName ' + err);
    }


})(request, response);
